import type { Table as TanstackTable, TableState } from "@tanstack/react-table";

import { createContext, useContext } from "react";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const ListContext = createContext<TanstackTable<any> | null>(null);
export const ListStateContext = createContext<TableState | null>(null);

export const useList = () => {
  const list = useContext(ListContext);
  const state = useContext(ListStateContext);

  if (!list || !state) {
    throw new Error("useList must be used within a <List> component");
  }

  return { ...list, state };
};
